"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[8379],{99950:e=>{e.exports=JSON.parse('{"tag":{"label":"Ecology & Biodiversity","permalink":"/science/tags/ecology-biodiversity","allTagsPath":"/science/tags","count":9,"items":[{"id":"2026/dangerous-animal-detection","title":"Dangerous Animal Detection and Alerting","description":"Authors: Saurav Koduri (University of Illinois Urbana-Champaign) and Avasyu Chukkapalli (Virginia Tech)","permalink":"/science/2026/dangerous-animal-detection"},{"id":"2026/bat","title":"Edge Acoustic Sensing for Bat Detection","description":"Authors: Jeongmin Chae (University of Southern California) and Julia Gersey (University of Michigan / Argonne National Lab)","permalink":"/science/2026/bat"},{"id":"2026/bisonn","title":"Exploring the Potential for Edge Computing to Collect Novel Biotic Interaction Data","description":"Kyle Lima","permalink":"/science/2026/bisonn"},{"id":"2026/manoomin-vision","title":"Manoomin Vision","description":"Authors: Jordan Gurneau (Northwestern University), Ella Neumann (Georgia Tech / MIT), Dave MacDonald (UC Davis), Deanna DiMonte (Northwestern University), and Morty (lead)","permalink":"/science/2026/manoomin-vision"},{"id":"2023/monitoring-biodiversity","title":"Monitoring biodiversity using acoustic data","description":"The Big Picture","permalink":"/science/2023/monitoring-biodiversity"},{"id":"2026/bat-counter","title":"Sage Bat Counter","description":"Authors: Noah Betoshana (University of California, Davis) and Liam Fitzpatrick (Michigan State University)","permalink":"/science/2026/bat-counter"},{"id":"2023/snow-detection","title":"Snow Classifier","description":"Ice and snowfall are incredibly important parts of a river ecosystem. The Bad River is home to wild rice, which is very temperamental and prone to natural boom/bust years. Having a snow classifier can be used to create a larger dataset of snow that can be used for a variety of these additional tasks including assisting with predicting wild rice yields.","permalink":"/science/2023/snow-detection"},{"id":"2024/sound-separation","title":"Sound Separation","description":"By processing data directly at the collection source, edge computing networks like Sage/Waggle offer unique advantages over using centralized servers for ecological monitoring tasks. Audio in particular is useful for tracking metrics like noise pollution from human development or population statistics for vocal wildlife in the area (birds, insects, frogs, etc.). Further analysis can provide deeper insights into the overall health of the ecosystems where nodes are deployed.","permalink":"/science/2024/sound-separation"},{"id":"2026/speech-redaction-at-the-edge","title":"Speech Redaction at the Edge","description":"Miguel Hernandez, Northwestern University","permalink":"/science/2026/speech-redaction-at-the-edge"}],"unlisted":false}}')}}]);